        /// The `CTRL0` register.
        ///
        /// Register
        pub mod ctrl0 {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0f83c00c;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// SAR clock divider
                #[inline]
                pub const fn sar1_trigger_mode(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 2)
                }

                /// 0 ~ 15 means length 1 ~ 16
                #[inline]
                pub const fn sar1_patt_len(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 14)
                }

                /// 1: select meas start as table update 0:select mead done as table update
                #[inline]
                pub const fn sar1_patt_type(self) -> bool {
                    (self.0 & 0x00800000) != 0
                }

                /// 1: sar_sel will be coded by the MSB of the 16-bit output data, in this case the resolution should not be larger than 11 bits.
                #[inline]
                pub const fn sar1_clk_pos_sel(self) -> bool {
                    (self.0 & 0x01000000) != 0
                }

                /// 1: I2S input data is from SAR ADC (for DMA), 0: I2S input data is from GPIO matrix
                #[inline]
                pub const fn sar1_continue_mode_en(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }

                /// force option to xpd sar1 blocks
                #[inline]
                pub const fn xpd_sar1_force(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 26)
                }
            }
        }

