                #[inline]
                pub const fn out_cmd_disable_ch1(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// 1: mean access ecc or aes domain,0: mean not
                #[inline]
                pub const fn out_ecc_aec_en_ch1(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

