        /// The block's declared words, as byte offsets from [`BASE`]: its
        /// whole register authority.
        pub struct BlockWords;

        impl oer_mmio::Registers for BlockWords {
            const WORDS: &'static [usize] =
                &[0x0, 0x4, 0x8, 0xc, 0x10, 0x28, 0x2c, 0x30, 0x3c, 0x40];
        }

        /// The block's device registers, as the PAC root claims them.
        pub type Claim = oer_mmio::Block<oer_mmio::Fixed<0x2039b000>, BlockWords>;

        /// The exclusive owner of the `CORDIC` registers.
        #[must_use = "dropping a register owner permanently loses its register authority"]
        pub struct Cordic<P: oer_mmio::Placement = oer_mmio::Fixed<0x2039b000>>(
            oer_mmio::Block<P, BlockWords>,
        );

        impl Cordic {
            /// The owner of the block's device registers.
            pub const fn new(block: Claim) -> Self {
                Self(block)
            }
        }

        impl<'a> Cordic<oer_mmio::Host<'a>> {
            /// The block over host memory, for tests of its accessors.
            pub fn host(words: &'a mut [u32]) -> Result<Self, oer_mmio::HostTooSmall> {
                oer_mmio::Block::host(words).map(Self)
            }
        }

        impl<P: oer_mmio::Placement> Cordic<P> {
            /// Read `CSR_CFG`.
            #[inline]
            pub fn read_csr_cfg(&self) -> csr_cfg::R {
                csr_cfg::R(self.0.read::<0x0>())
            }

            /// Read `ARG1`.
            #[inline]
            pub fn read_arg1(&self) -> arg1::R {
                arg1::R(self.0.read::<0x4>())
            }

            /// Read `ARG1`, change fields and write it back; every other bit keeps
            /// the value read.
            #[inline]
            pub fn modify_arg1(&mut self, change: impl FnOnce(&mut arg1::W)) {
                let mut value = arg1::W(self.0.read::<0x4>());
                change(&mut value);
                self.0.write::<0x4>(value.0);
            }

            /// Read `ARG2`.
            #[inline]
            pub fn read_arg2(&self) -> arg2::R {
                arg2::R(self.0.read::<0x8>())
            }

            /// Read `ARG2`, change fields and write it back; every other bit keeps
            /// the value read.
            #[inline]
            pub fn modify_arg2(&mut self, change: impl FnOnce(&mut arg2::W)) {
                let mut value = arg2::W(self.0.read::<0x8>());
                change(&mut value);
                self.0.write::<0x8>(value.0);
            }

            /// Read `RES1`.
            #[inline]
            pub fn read_res1(&self) -> res1::R {
                res1::R(self.0.read::<0xc>())
            }

            /// Read `RES2`.
            #[inline]
            pub fn read_res2(&self) -> res2::R {
                res2::R(self.0.read::<0x10>())
            }

            /// Read `IO_INT_ENA`.
            #[inline]
            pub fn read_io_int_ena(&self) -> io_int_ena::R {
                io_int_ena::R(self.0.read::<0x28>())
            }

            /// Read `IO_INT_RAW`.
            #[inline]
            pub fn read_io_int_raw(&self) -> io_int_raw::R {
                io_int_raw::R(self.0.read::<0x2c>())
            }

            /// Read `IO_INT_ST`.
            #[inline]
            pub fn read_io_int_st(&self) -> io_int_st::R {
                io_int_st::R(self.0.read::<0x30>())
            }

            /// Read `CLK`.
            #[inline]
            pub fn read_clk(&self) -> clk::R {
                clk::R(self.0.read::<0x3c>())
            }

            /// Read `VERSION`.
            #[inline]
            pub fn read_version(&self) -> version::R {
                version::R(self.0.read::<0x40>())
            }
        }

