        /// The `IN_CONF0_CH%s` register.
        ///
        /// Configures the rx direction of channel %s
        pub mod in_conf0_ch {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x07011ffd;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x500;

            /// The byte distance between two elements of the array.
            pub const STRIDE: usize = 0x100;
            /// The array's element count.
            pub const COUNT: usize = 3;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// enable memory trans of the same channel
                #[inline]
                pub const fn in_mem_trans_en_ch(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Set this bit to 1 to enable INCR burst transfer for Rx transmitting link descriptor when accessing SRAM.
                #[inline]
                pub const fn indscr_burst_en_ch(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// When access address space is ecc/aes area, this bit should be set to 1. In this case, the start address of square should be 16-bit aligned. The width of square multiply byte number of one pixel should be 16-bit aligned.
                #[inline]
                pub const fn in_ecc_aes_en_ch(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// Set this bit to enable checking the owner attribute of the link descriptor.
                #[inline]
                pub const fn in_check_owner_ch(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// reserved
                #[inline]
                pub const fn in_loop_test_ch(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Block size of Rx channel 0. 0: single 1: 16 bytes 2: 32 bytes 3: 64 bytes 4: 128 bytes
                #[inline]
                pub const fn in_mem_burst_length_ch(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 6)
                }

                /// Sel RX macro-block size 0: 8pixel*8pixel 1: 8pixel*16pixel 2: 16pixel*16pixel 3: no macro-block , only useful in mode 1 of the link descriptor
                #[inline]
                pub const fn in_macro_block_size_ch(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 9)
                }

                /// Set this bit to 1 to obtain descriptor from IP port
                #[inline]
                pub const fn in_dscr_port_en_ch(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Set this bit to 1 to make sure AXI write data don't cross the address boundary which define by mem_burst_length
                #[inline]
                pub const fn in_page_bound_en_ch(self) -> bool {
                    (self.0 & 0x00001000) != 0
                }

                /// Enable RX channel 0 macro block reorder when set to 1, only channel0 have this selection
                #[inline]
                pub const fn in_reorder_en_ch(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Write 1 then write 0 to this bit to reset Rx channel
                #[inline]
                pub const fn in_rst_ch(self) -> bool {
                    (self.0 & 0x01000000) != 0
                }

                /// Write 1 before reset and write 0 after reset
                #[inline]
                pub const fn in_cmd_disable_ch(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }

                /// Set this bit to 1 to disable arbiter optimum weight function.
                #[inline]
                pub const fn in_arb_weight_opt_dis_ch(self) -> bool {
                    (self.0 & 0x04000000) != 0
                }
            }
        }

