        /// Gives the status of various internal blocks for debugging
        pub mod register9_debugregister {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x037f0377;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x24;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// MAC GMII or MII Receive Protocol Engine Status When high, this bit indicates that the MAC GMII or MII receive protocol engine is actively receiving data and not in IDLE state
                #[inline]
                pub const fn rpests(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// MAC Receive Frame FIFO Controller Status When high, this field indicates the active state of the small FIFO Read and Write controllers of the MAC Receive Frame Controller Module RFCFCSTS\[1\] represents the status of small FIFO Read controller RFCFCSTS\[0\] represents the status of small FIFO Write controller
                #[inline]
                pub const fn rfcfcsts(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 1)
                }

                /// MTL Rx FIFO Write Controller Active Status When high, this bit indicates that the MTL Rx FIFO Write Controller is active and is transferring a received frame to the FIFO
                #[inline]
                pub const fn rwcsts(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// MTL RxFIFO Read Controller State This field gives the state of the Rx FIFO read Controller: 00: IDLE state 01: Reading frame data 10: Reading frame status _or timestamp_ 11: Flushing the frame data and status
                #[inline]
                pub const fn rrcsts(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 5)
                }

                /// MTL RxFIFO FillLevel Status This field gives the status of the filllevel of the Rx FIFO: 00: Rx FIFO Empty 01: Rx FIFO filllevel below flowcontrol deactivate threshold 10: Rx FIFO filllevel above flowcontrol activate threshold 11: Rx FIFO Full
                #[inline]
                pub const fn rxfsts(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 8)
                }

                /// MAC GMII or MII Transmit Protocol Engine Status When high, this bit indicates that the MAC GMII or MII transmit protocol engine is actively transmitting data and is not in the IDLE state
                #[inline]
                pub const fn tpests(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// MAC Transmit Frame Controller Status This field indicates the state of the MAC Transmit Frame Controller module: 00: IDLE state 01: Waiting for status of previous frame or IFG or backoff period to be over 10: Generating and transmitting a Pause frame _in the fullduplex mode_ 11: Transferring input frame for transmission
                #[inline]
                pub const fn tfcsts(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 17)
                }

                /// MAC Transmitter in Pause When high, this bit indicates that the MAC transmitter is in the Pause condition _in the fullduplexonly mode_ and hence does not schedule any frame for transmission
                #[inline]
                pub const fn txpaused(self) -> bool {
                    (self.0 & 0x00080000) != 0
                }

                /// MTL Tx FIFO Read Controller Status This field indicates the state of the Tx FIFO Read Controller: 00: IDLE state 01: READ state _transferring data to the MAC transmitter_ 10: Waiting for TxStatus from the MAC transmitter 11: Writing the received TxStatus or flushing the Tx FIFO
                #[inline]
                pub const fn trcsts(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 20)
                }

                /// MTL Tx FIFO Write Controller Status When high, this bit indicates that the MTL Tx FIFO Write Controller is active and is transferring data to the Tx FIFO
                #[inline]
                pub const fn twcsts(self) -> bool {
                    (self.0 & 0x00400000) != 0
                }

                /// MTL Tx FIFO Not Empty Status When high, this bit indicates that the MTL Tx FIFO is not empty and some data is left for transmission
                #[inline]
                pub const fn txfsts(self) -> bool {
                    (self.0 & 0x01000000) != 0
                }

                /// MTL TxStatus FIFO Full Status When high, this bit indicates that the MTL TxStatus FIFO is full Therefore, the MTL cannot accept any more frames for transmission This bit is reserved in the GMACAHB and GMACDMA configurations
                #[inline]
                pub const fn txstsfsts(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }
            }
        }

