        /// The `REGISTER48_ANCONTROLREGISTER` register.
        ///
        /// Enables and/or restarts autonegotiation This register also enables the Physical Coding Sublayer _PCS_ loopback This register is present only when you select the TBI, RTBI, or SGMII interface in coreConsultant
        pub mod register48_ancontrolregister {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00075200;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0xc0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Restart AutoNegotiation When set, this bit causes autonegotiation to restart if Bit 12 _ANE_ is set This bit is selfclearing after autonegotiation starts This bit should be cleared for normal operation
                #[inline]
                pub const fn ran(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// AutoNegotiation Enable When set, this bit enables the MAC to perform autonegotiation with the link partner Clearing this bit disables the autonegotiation
                #[inline]
                pub const fn ane(self) -> bool {
                    (self.0 & 0x00001000) != 0
                }

                /// External Loopback Enable When set, this bit causes the PHY to loopback the transmit data into the receive path The pcs_ewrap_o signal is asserted high when this bit is set
                #[inline]
                pub const fn ele(self) -> bool {
                    (self.0 & 0x00004000) != 0
                }

                /// Enable Comma Detect When set, this bit enables the PHY for comma detection and word resynchronization This bit controls the pcs_en_cdet_o signal on the TBI, RTBI, or SGMII interface
                #[inline]
                pub const fn ecd(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Lock to Reference When set, this bit enables the PHY to lock its PLL to the 125 MHz reference clock This bit controls the pcs_lck_ref_o signal on the TBI, RTBI, or SGMII interface
                #[inline]
                pub const fn lr(self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// SGMII RAL Control When set, this bit forces the SGMII RAL block to operate in the speed configured in the Speed and Port Select bits of the MAC Configuration register This is useful when the SGMII interface is used in a direct MAC to MAC connection _without a PHY_ and any MAC must reconfigure the speed When reset, the SGMII RAL block operates according to the link speed status received on SGMII _from the PHY_ This bit is reserved _and RO_ if the SGMII PHY interface is not selected during core configuration
                #[inline]
                pub const fn sgmral(self) -> bool {
                    (self.0 & 0x00040000) != 0
                }
            }
        }

        /// The `REGISTER49_ANSTATUSREGISTER` register.
        ///
        /// Indicates the link and autonegotiation status This register is present only when you select the TBI, RTBI, or SGMII interface in coreConsultant
        pub mod register49_anstatusregister {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0000012c;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0xc4;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Link Status This bit indicates whether the data channel _link_ is up or down For the TBI, RTBI or SGMII interfaces, if ANEG is going on, data cannot be transferred across the link and hence the link is given as down
                #[inline]
                pub const fn ls(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// AutoNegotiation Ability This bit is always high because the MAC supports auto negotiation
                #[inline]
                pub const fn ana(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// AutoNegotiation Complete When set, this bit indicates that the autonegotiation process is complete This bit is cleared when autonegotiation is reinitiated
                #[inline]
                pub const fn anc(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Extended Status This bit is tied to high if the TBI or RTBI interface is selected during core configuration indicating that the MAC supports extended status information in Register 53 _TBI Extended Status Register_ This bit is tied to low if the SGMII interface is selected and the TBI or RTBI interface is not selected during core configuration indicating that Register 53 is not present
                #[inline]
                pub const fn es(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }
            }
        }

