                #[inline]
                pub const fn ch1_ete(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Fatal Bus Error Enable When this bit is set with Abnormal Interrupt Summary Enable _Bit 15_, the Fatal Bus Error Interrupt is enabled When this bit is reset, the Fatal Bus Error Enable Interrupt is disabled 12:11 Reserved 00 RO
                #[inline]
                pub const fn ch1_fbe(self) -> bool {
                    (self.0 & 0x00002000) != 0
                }

