        /// The `REGISTER136_CHANNEL2MISSEDFRAMEANDBUFFEROVERFLOWCOUNTERREGISTER` register.
        ///
        /// Contains the counters for discarded frames because no host Receive Descriptor was available or because of Receive FIFO Overflow
        pub mod register136_channel2missedframeandbufferoverflowcounterregister {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x1fffffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x1220;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Missed Frame Counter This field indicates the number of frames missed by the controller because of the Host Receive Buffer being unavailable This counter is incremented each time the DMA discards an incoming frame The counter is cleared when this register is read with mci_be_i\[0\] at 1’b1
                #[inline]
                pub const fn ch2_misfrmcnt(self) -> u16 {
                    (self.0) as u16
                }

                /// Overflow Bit for Missed Frame Counter This bit is set every time Missed Frame Counter _Bits\[15:0\]_ overflows, that is, the DMA discards an incoming frame because of the Host Receive Buffer being unavailable with the missed frame counter at maximum value In such a scenario, the Missed frame counter is reset to allzeros and this bit indicates that the rollover happened
                #[inline]
                pub const fn ch2_miscntovf(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Overflow Frame Counter This field indicates the number of frames missed by the application This counter is incremented each time the MTL FIFO overflows The counter is cleared when this register is read with mci_be_i\[2\] at 1’b1
                #[inline]
                pub const fn ch2_ovffrmcnt(self) -> oer_mmio::Bits<11> {
                    oer_mmio::Bits::truncate(self.0 >> 17)
                }

                /// Overflow Bit for FIFO Overflow Counter This bit is set every time the Overflow Frame Counter _Bits\[27:17\]_ overflows, that is, the Rx FIFO overflows with the overflow frame counter at maximum value In such a scenario, the overflow frame counter is reset to allzeros and this bit indicates that the rollover happened
                #[inline]
                pub const fn ch2_ovfcntovf(self) -> bool {
                    (self.0 & 0x10000000) != 0
                }
            }
        }

