        /// The `VER_DATE` register.
        ///
        /// need_des
        pub mod ver_date {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffffffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// need_des
                #[inline]
                pub const fn ver_date(self) -> oer_mmio::Bits<31> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// need_des
                #[inline]
                pub const fn clk_en(self) -> bool {
                    (self.0 & 0x80000000) != 0
                }
            }

            /// The register's value while it is changed.
            pub struct W(pub(super) u32);

            impl W {
                /// need_des
                #[inline]
                pub const fn ver_date(&self) -> oer_mmio::Bits<31> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// need_des
                #[inline]
                pub const fn clk_en(&self) -> bool {
                    (self.0 & 0x80000000) != 0
                }

                /// Set `VER_DATE`.
                #[inline]
                pub fn set_ver_date(&mut self, value: oer_mmio::Bits<31>) -> &mut Self {
                    self.0 = (self.0 & !0x7fffffff) | value.get();
                    self
                }

                /// Set `CLK_EN`.
                #[inline]
                pub fn set_clk_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x80000000) | (u32::from(value) << 31);
                    self
                }
            }
        }

