        ///
        /// HUK Generator HUK status register
        pub mod status {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0000003f;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x34;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// The HUK generation status. 0: HUK is not generated. 1: HUK is generated and valid. 2: HUK is generated but invalid. 3: reserved.
                #[inline]
                pub const fn status(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// The risk level of HUK. 0-6: the higher the risk level is, the more error bits there are in the PUF SRAM. 7: Error Level, HUK is invalid.
                #[inline]
                pub const fn risk_level(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 2)
                }

                /// The update request of HUK info. 0: User can update HUK info according to the risk level. 1: The HUK info is expired, and user need to update it.
                #[inline]
                pub const fn update_req(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }
            }
        }

