            /// hardware action once; every other field keeps the value read, every other trigger is zero.
            #[inline]
            pub fn trigger_lpcpu_ctrl_lpcpu_sw_sleep_req(&mut self) {
                self.0
                    .write::<0x8>((self.0.read::<0x8>() & !lpcpu_ctrl::TRIGGERS) | 0x00000001);
            }

