        /// The `CONFIG` register.
        ///
        /// Configures RMA algorithm
        pub mod config {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00007ffb;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Configures the RMA module. \\ 00: REQUEST CERTIFICATE\\ 01: VERIFICATION CERTIFICATE\\ 10: FAST VERIFICATION\\
                #[inline]
                pub const fn work_mode(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Whether enable JTAG after RMA pass. \\ 0: Do not enable JTAG \\ 1: Enable JTAG \\
                #[inline]
                pub const fn reuse_jtag(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// Whether enable DOWNLOAD_MODE after RMA pass. \\ 0: Do not enable DOWNLOAD mode\\ 1: Enable DOWNLOAD\\
                #[inline]
                pub const fn reuse_download(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// Whether enable FORCE_SPI_BOOT after RMA pass. \\ 0: Do not enable FORCE_SPI_BOOT mode\\ 1: Enable FORCE_SPI_BOOT\\
                #[inline]
                pub const fn force_spi(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Whether use NONCE. \\ 0: Do not use NONCE\\ 1: Use NONCE\\
                #[inline]
                pub const fn use_nonce(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// Whether use km to gnerate NONCE. \\ 0: Do not use KM to generate NONCE \\ 1: Use KM to generate NONCE\\
                #[inline]
                pub const fn use_km(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// The length of USC.
                #[inline]
                pub const fn usc_block_num(self) -> oer_mmio::Bits<7> {
                    oer_mmio::Bits::truncate(self.0 >> 8)
                }
            }
        }

        /// The `STATE` register.
        ///
        /// query state in rma
        pub mod state {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00000007;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x8;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// The status bits of RMA Accelerator. RMA is at 0: IDLE, 1: LOAD, 2: GAIN, 3: USC, 4: LOCK, others: BUSY state.
                #[inline]
                pub const fn state(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0)
                }
            }
        }

        /// The `LOG` register.
        ///
        /// Query result in rma
        pub mod log {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xf0000007;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0xc;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Marks state of rma cert verification result. \\ 1: pass\\ 0: failed\\
                #[inline]
                pub const fn cert_state(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Marks state of rma public key verification result. \\ 1: pass\\ 0: failed\\
                #[inline]
                pub const fn public_key_state(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// Marks state of rma sign verification result. \\ 1: pass\\ 0: failed\\
                #[inline]
                pub const fn sign_state(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// Marks error nonce config . \\ 0 : Use efuse_hash_sg in CERT_REQ or FAST_VEF but key invalid\\ 1 : Nonce config pass.
                #[inline]
                pub const fn nonce_state(self) -> bool {
                    (self.0 & 0x10000000) != 0
                }

                /// Marks error KM config . \\ 0 : Use km but km key invalid\\ 1 : KM config pass\\
                #[inline]
                pub const fn km_state(self) -> bool {
                    (self.0 & 0x20000000) != 0
                }

                /// Marks error mode config . \\ 0 : Invalid mode config\\ 1 : MODE config pass\\
                #[inline]
                pub const fn mode_state(self) -> bool {
                    (self.0 & 0x40000000) != 0
                }

                /// Marks efuse state . \\ 0 : Efuse disable RMA module\\ 1 : Efuse pass\\
                #[inline]
                pub const fn efuse_state(self) -> bool {
                    (self.0 & 0x80000000) != 0
                }
            }
        }

