        /// The `DEVICE_ID_VERSION` register.
        ///
        /// TWAI FD device id status register
        pub mod device_id_version {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffffffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Represents whether CAN IP function is mapped correctly on its base address.
                #[inline]
                pub const fn device_id(self) -> u16 {
                    (self.0) as u16
                }

                /// TWAI FD IP version
                #[inline]
                pub const fn ver_minor(self) -> u8 {
                    (self.0 >> 16) as u8
                }

                /// TWAI FD IP version
                #[inline]
                pub const fn ver_major(self) -> u8 {
                    (self.0 >> 24) as u8
                }
            }
        }

        /// The `MODE_SETTINGS` register.
        ///
        /// TWAI FD mode setting register
        pub mod mode_settings {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0fff0ffe;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x4;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Bus monitoring mode. In this mode CTU CAN FD only receives frames and sends only recessive bits on CAN bus. When a dominant bit is sent, it is re-routed internally so that bus value is not changed. When this mode is enabled, CTU CAN FD will not transmit any frame from TXT Buffers, 0b0 - BMM_DISABLED - Bus monitoring mode disabled. 0b1 - BMM_ENABLED - Bus monitoring mode enabled.
                #[inline]
                pub const fn bmm(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// Self Test Mode. In this mode transmitted frame is considered valid even if dominant acknowledge was not received. 0b0 - STM_DISABLED - Self test mode disabled. 0b1 - STM_ENABLED - Self test mode enabled.
                #[inline]
                pub const fn stm(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// Acceptance Filters Mode. If enabled, only RX frames which pass Frame filters are stored in RX buffer. If disabled, every received frame is stored to RX buffer. This bit has meaning only if there is at least one filter available. Otherwise, this bit is reserved. 0b0 - AFM_DISABLED - Acceptance filter mode disabled 0b1 - AFM_ENABLED - Acceptance filter mode enabled
                #[inline]
                pub const fn afm(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// Flexible data rate enable. When flexible data rate is enabled CTU CAN FD recognizes CAN FD frames (FDF bit = 1). 0b0 - FDE_DISABLE - Flexible data-rate support disabled. 0b1 - FDE_ENABLE - Flexible data-rate support enabled.
                #[inline]
                pub const fn fde(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// Time triggered transmission mode. 0b0 - TTTM_DISABLED - 0b1 - TTTM_ENABLED -
                #[inline]
                pub const fn tttm(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Restricted operation mode. 0b0 - ROM_DISABLED - Restricted operation mode is disabled. 0b1 - ROM_ENABLED - Restricted operation mode is enabled.
                #[inline]
                pub const fn rom(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// Acknowledge Forbidden Mode. When enabled, acknowledge is not sent even if received CRC matches the calculated one. 0b0 - ACF_DISABLED - Acknowledge forbidden mode disabled. 0b1 - ACF_ENABLED - Acknowledge forbidden mode enabled.
                #[inline]
                pub const fn acf(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// Test Mode. In test mode several registers have special features. Reffer to description of Test mode for further Details.
                #[inline]
                pub const fn tstm(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// RX Buffer automatic mode. 0b0 - RXBAM_DISABLED - 0b1 - RXBAM_ENABLED -
                #[inline]
                pub const fn rxbam(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// TXT Buffer Backup mode\\ 0b0 - TXBBM_DISABLED - TXT Buffer Backup mode disabled\\ 0b1 - TXBBM_ENABLED - TXT Buffer Backup mode enabled\\
                #[inline]
                pub const fn txbbm(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Self-acknowledge mode.\\ 0b0 - SAM_DISABLE - Do not send dominant ACK bit when CTU CAN FD sends Acknowledge bit.\\ 0b1 - SAM_ENABLE - Send dominant ACK bit when CTU CAN FD transmits CAN frame.\\
                #[inline]
                pub const fn sam(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Retransmitt Limit Enable. If enabled, CTU CAN FD only attempts to retransmitt each frame up to RTR_TH times. 0b0 - RTRLE_DISABLED - Retransmitt limit is disabled. 0b1 - RTRLE_ENABLED - Retransmitt limit is enabled.
                #[inline]
                pub const fn rtrle(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Retransmitt Limit Threshold. Maximal amount of retransmission attempts when SETTINGS\[RTRLE\] is en- Abled.
                #[inline]
                pub const fn rtrth(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 17)
                }

                /// Internal Loop Back mode. When enabled, CTU CAN FD receives any frame it transmitts. 0b0 - INT_LOOP_DISABLED - Internal loop-back is disabled. 0b1 - INT_LOOP_ENABLED - Internal loop-back is enabled.
                #[inline]
                pub const fn ilbp(self) -> bool {
                    (self.0 & 0x00200000) != 0
                }

                /// Main enable bit of CTU CAN FD. When enabled, CTU CAN FD communicates on CAN bus. When disabled, it is bus-off and does not take part of CAN bus communication. 0b0 - CTU_CAN_DISABLED - The CAN Core is disabled. 0b1 - CTU_CAN_ENABLED - The CAN Core is enabled.
                #[inline]
                pub const fn ena(self) -> bool {
                    (self.0 & 0x00400000) != 0
                }

                /// Non ISO FD. When this bit is set, CTU CAN FD is compliant to NON-ISO CAN FD specification (no stuff count field). This bit should be modified only when SETTINGS\[ENA\]=0. 0b0 - ISO_FD - The CAN Controller conforms to ISO CAN FD specification. 0b1 - NON_ISO_FD - The CAN Controller conforms to NON ISO CAN FD specification. CANFD 1.0
                #[inline]
                pub const fn nisofd(self) -> bool {
                    (self.0 & 0x00800000) != 0
                }

                /// Protocol exception handling. When this bit is set, CTU CAN FD will start integration upon detection of protocol exception. This should be modified only when SETTINGS\[ENA\] = ’0’. 0b0 - PROTOCOL_EXCEPTION_DISABLED - Protocol exception handling is disabled. 0b1 - PROTOCOL_EXCEPTION_ENABLED - Protocol exception handling is enabled.
                #[inline]
                pub const fn pex(self) -> bool {
                    (self.0 & 0x01000000) != 0
                }

                /// All TXT buffers shall go to "TX failed" state when CTU CAN FD becomes bus-off. 0b0 - TXTBUF_FAILED_BUS_OFF_DISABLED - TXT Buffers dont go to "TX failed" state when CTU CAN FD becomes bus-off. 0b1 - TXTBUF_FAILED_BUS_OFF_ENABLED - TXT Buffers go to "TX failed" state when CTU CAN FD becomes bus-off.
                #[inline]
                pub const fn tbfbo(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }

                /// Frame filters drop Remote frames. 0b0 - DROP_RF_DISABLED - Frame filters accept RTR frames. 0b1 - DROP_RF_ENABLED - Frame filters drop RTR frames.
                #[inline]
                pub const fn fdrf(self) -> bool {
                    (self.0 & 0x04000000) != 0
                }

                /// Enable Parity checks in TXT Buffers and RX Buffer.
                #[inline]
                pub const fn pchke(self) -> bool {
                    (self.0 & 0x08000000) != 0
                }
            }
        }

        /// The `STATUS` register.
        ///
        /// TWAI FD status register
        pub mod status {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00070fff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x8;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// RX buffer not empty. This bit is 1 when least one frame is stored in RX buffer. 0: empty 1: not empty
                #[inline]
                pub const fn rxne(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Data Overrun flag. This bit is set when frame was dropped due to lack of space in RX buffer. This bit can be cleared by COMMAND\[RRB\]. 0: not overrun 1: overrun
                #[inline]
                pub const fn dor(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// TXT buffers status. This bit is set if at least one TXT buffer is in "Empty" state. 0: not full 1: full
                #[inline]
                pub const fn txnf(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// Error frame is being transmitted at the moment. 0: not being transmitted 1: being transmitted
                #[inline]
                pub const fn eft(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// CTU CAN FD is receiver of CAN Frame. 0: not receiving 1: receiving
                #[inline]
                pub const fn rxs(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// CTU CAN FD is transmitter of CAN Frame. 0: not transmitting 1: transmitting
                #[inline]
                pub const fn txs(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// TX Error counter (TEC) or RX Error counter (REC) is equal to, or higher than Error warning limit (EWL). 0: not reached 1: reached
                #[inline]
                pub const fn ewl(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// Bus is idle (no frame is being transmitted/received) or CTU CAN FD is bus-off. 0: active 1: not active
                #[inline]
                pub const fn idle(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// Protocol exception status (flag). Set when Protocol exception occurs. Cleared by writing COMMAND\[CPEXS\]=1.
                #[inline]
                pub const fn pexs(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// Set when parity error is detected during read of CAN frame from RX Buffer via RX_DATA register.
                #[inline]
                pub const fn rxpe(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// TXT Buffers Parity Error flag. Set When Parity Error is detected in a TXT Buffer during transmission from this Buffer.
                #[inline]
                pub const fn txpe(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// TXT Buffer double parity error. Set in TXT Buffer Backup mode when parity error is detected in "backup" TXT Buffer.
                #[inline]
                pub const fn txdpe(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Support of Traffic counters. When this bit is 1, Traffic counters are present.
                #[inline]
                pub const fn stcnt(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Support of Test Registers for memory testability. When this bit is 1, Test Registers are present.
                #[inline]
                pub const fn strgs(self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// Support of Parity protection on each word of TXT Buffer RAM and RX Buffer RAM.
                #[inline]
                pub const fn sprt(self) -> bool {
                    (self.0 & 0x00040000) != 0
                }
            }
        }

        /// The `INT_STAT` register.
        ///
        /// TWAI FD command register
        pub mod int_stat {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00000fff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x10;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// The masked interrupt status of TWAIFD_RXI_INT. Frame received interrupt.
                #[inline]
                pub const fn rxi_int_st(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// The masked interrupt status of TWAIFD_TXI_INT. Frame transmitted interrupt.
                #[inline]
                pub const fn txi_int_st(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// The masked interrupt status of TWAIFD_EWLI_INT. Error warning limit interrupt. When both TEC and REC are lower than EWL and one of the becomes equal to or higher than EWL, or when both TEC and REC become less than EWL, this interrupt is generated. When Interrupt is cleared and REC, or TEC is still equal to or higher than EWL, Interrupt is not generated again.
                #[inline]
                pub const fn ewli_int_st(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// The masked interrupt status of TWAIFD_DOI_INT. Data overrun interrupt. Before this Interrupt is cleared , STATUS\[DOR\] must be cleared to avoid setting of this Interrupt again.
                #[inline]
                pub const fn doi_int_st(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// The masked interrupt status of TWAIFD_FCSI_INT. Fault confinement state changed interrupt. Interrupt is set when node turns error-passive (from error-active), bus-off (from error-passive) or error-active (from bus-off after reintegration or from error-passive).
                #[inline]
                pub const fn fcsi_int_st(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// The masked interrupt status of TWAIFD_ALI_INT. Arbitration lost interrupt.
                #[inline]
                pub const fn ali_int_st(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// The masked interrupt status of TWAIFD_BEI_INT. Bus error interrupt.
                #[inline]
                pub const fn bei_int_st(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// The masked interrupt status of TWAIFD_OFI_INT. Overload frame interrupt.
                #[inline]
                pub const fn ofi_int_st(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// The masked interrupt status of TWAIFD_RXFI_INT. RX buffer full interrupt.
                #[inline]
                pub const fn rxfi_int_st(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// The masked interrupt status of TWAIFD_BSI_INT. Bit rate shifted interrupt.
                #[inline]
                pub const fn bsi_int_st(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// The masked interrupt status of TWAIFD_RBNEI_INT. RX buffer not empty interrupt. Clearing this interrupt and not reading out content of RX Buffer via RX_DATA will re-activate the interrupt.
                #[inline]
                pub const fn rbnei_int_st(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// The masked interrupt status of TWAIFD_TXBHCI_INT. TXT buffer HW command interrupt. Anytime TXT buffer receives HW command from CAN Core which changes TXT buffer state to "TX OK", "Error" or "Aborted", this interrupt will be generated.
                #[inline]
                pub const fn txbhci_int_st(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }
            }
        }

