        /// The `DEBUG` register.
        ///
        /// TWAI FD debug register
        pub mod debug {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0007ffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x8c;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Actual stuff count modulo 8 as definned in ISO FD protocol. Stuff count is erased in the beginning of CAN frame and increased by one with each stuff bit until Stuff count field in ISO FD frame. Then it stays fixed until the beginning of next frame. In non-ISO FD or normal CAN stuff bits are counted until the end of a frame. Note that this field is NOT gray encoded as defined in ISO FD standard. Stuff count is calculated only as long as controller is transceiving on the bus. During the reception this value remains fixed!
                #[inline]
                pub const fn stuff_count(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Actual de-stuff count modulo 8 as defined in ISO FD protocol. De-Stuff count is erased in the beginning of the frame and increased by one with each de-stuffed bit until Stuff count field in ISO FD Frame. Then it stays fixed until beginning of next frame. In non-ISO FD or normal CAN de-stuff bits are counted until the end of the frame. Note that this field is NOT grey encoded as defined in ISO FD standard. De-stuff count is calculated in both. Transceiver as well as receiver.
                #[inline]
                pub const fn destuff_count(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 3)
                }

                /// Protocol control state machine is in Arbitration field.
                #[inline]
                pub const fn pc_arb(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// Protocol control state machine is in Control field.
                #[inline]
                pub const fn pc_con(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// Protocol control state machine is in Data field.
                #[inline]
                pub const fn pc_dat(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// Protocol control state machine is in Stuff Count field.
                #[inline]
                pub const fn pc_stc(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// Protocol control state machine is in CRC field.
                #[inline]
                pub const fn pc_crc(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Protocol control state machine is in CRC Delimiter field.
                #[inline]
                pub const fn pc_crcd(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Protocol control state machine is in ACK field.
                #[inline]
                pub const fn pc_ack(self) -> bool {
                    (self.0 & 0x00001000) != 0
                }

                /// Protocol control state machine is in ACK Delimiter field.
                #[inline]
                pub const fn pc_ackd(self) -> bool {
                    (self.0 & 0x00002000) != 0
                }

                /// Protocol control state machine is in End of file field.
                #[inline]
                pub const fn pc_eof(self) -> bool {
                    (self.0 & 0x00004000) != 0
                }

                /// Protocol control state machine is in Intermission field.
                #[inline]
                pub const fn pc_int(self) -> bool {
                    (self.0 & 0x00008000) != 0
                }

                /// Protocol control state machine is in Suspend transmission field.
                #[inline]
                pub const fn pc_susp(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// Protocol control state machine is in Overload field.
                #[inline]
                pub const fn pc_ovr(self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// Protocol control state machine is in Start of frame field.
                #[inline]
                pub const fn pc_sof(self) -> bool {
                    (self.0 & 0x00040000) != 0
                }
            }
        }

