        /// The `BTR` register.
        ///
        /// TWAI FD bit-timing register
        pub mod btr {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffffffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x24;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Configures the propagation segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn prop(self) -> oer_mmio::Bits<7> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Configures the phase 1 segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn ph1(self) -> oer_mmio::Bits<6> {
                    oer_mmio::Bits::truncate(self.0 >> 7)
                }

                /// Configures the phase 2 segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn ph2(self) -> oer_mmio::Bits<6> {
                    oer_mmio::Bits::truncate(self.0 >> 13)
                }

                /// Configures the baud-rate prescaler of nominal bit rate. Measurement unit: cycle of core clock.
                #[inline]
                pub const fn brp(self) -> u8 {
                    (self.0 >> 19) as u8
                }

                /// Represents the synchronization jump width in nominal bit time. Measurement unit: time quanta
                #[inline]
                pub const fn sjw(self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 27)
                }
            }

            /// The register's value while it is changed.
            pub struct W(pub(super) u32);

            impl W {
                /// Configures the propagation segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn prop(&self) -> oer_mmio::Bits<7> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Configures the phase 1 segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn ph1(&self) -> oer_mmio::Bits<6> {
                    oer_mmio::Bits::truncate(self.0 >> 7)
                }

                /// Configures the phase 2 segment of nominal bit rate. Measurement unit: time quanta
                #[inline]
                pub const fn ph2(&self) -> oer_mmio::Bits<6> {
                    oer_mmio::Bits::truncate(self.0 >> 13)
                }

                /// Configures the baud-rate prescaler of nominal bit rate. Measurement unit: cycle of core clock.
                #[inline]
                pub const fn brp(&self) -> u8 {
                    (self.0 >> 19) as u8
                }

                /// Represents the synchronization jump width in nominal bit time. Measurement unit: time quanta
                #[inline]
                pub const fn sjw(&self) -> oer_mmio::Bits<5> {
                    oer_mmio::Bits::truncate(self.0 >> 27)
                }

                /// Set `PROP`.
                #[inline]
                pub fn set_prop(&mut self, value: oer_mmio::Bits<7>) -> &mut Self {
                    self.0 = (self.0 & !0x0000007f) | value.get();
                    self
                }

                /// Set `PH1`.
                #[inline]
                pub fn set_ph1(&mut self, value: oer_mmio::Bits<6>) -> &mut Self {
                    self.0 = (self.0 & !0x00001f80) | (value.get() << 7);
                    self
                }

                /// Set `PH2`.
                #[inline]
                pub fn set_ph2(&mut self, value: oer_mmio::Bits<6>) -> &mut Self {
                    self.0 = (self.0 & !0x0007e000) | (value.get() << 13);
                    self
                }

                /// Set `BRP`.
                #[inline]
                pub fn set_brp(&mut self, value: u8) -> &mut Self {
                    self.0 = (self.0 & !0x07f80000) | (u32::from(value) << 19);
                    self
                }

                /// Set `SJW`.
                #[inline]
                pub fn set_sjw(&mut self, value: oer_mmio::Bits<5>) -> &mut Self {
                    self.0 = (self.0 & !0xf8000000) | (value.get() << 27);
                    self
                }
            }
        }

