        /// The `CONF0` register.
        ///
        /// UHCI configuration register
        pub mod conf0 {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x00001fff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Write 1 and then write 0 to reset the decoder state machine.
                #[inline]
                pub const fn tx_rst(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Write 1 and then write 0 to reset the encoder state machine.
                #[inline]
                pub const fn rx_rst(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// Configures to select which uart to connect with UHCI.\\ 0: UART0\\ 1: UART1\\
                #[inline]
                pub const fn uart_sel(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 2)
                }

                /// Configures whether or not to separate the data frame with a special character.\\ 0: Not separate\\ 1: Separate\\
                #[inline]
                pub const fn seper_en(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Configures whether or not to encode the data packet with a formatting header.\\ 0: Not use formatting header\\ 1: Use formatting header\\
                #[inline]
                pub const fn head_en(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// Configures whether or not to enable the reception of the 16-bit CRC.\\ 0: Disable\\ 1: Enable\\
                #[inline]
                pub const fn crc_rec_en(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// Configures whether or not to stop receiving data when UART is idle.\\ 0: Not stop\\ 1: Stop\\
                #[inline]
                pub const fn uart_idle_eof_en(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }

                /// Configures when the UHCI decoder stops receiving data.\\ 0: Stops after receiving 0xC0\\ 1: Stops when the number of received data bytes reach the specified value. When UHCI_HEAD_EN is 1, the specified value is the data length indicated by the UHCI packet header. when UHCI_HEAD_EN is 0, the specified value is the configured value.\\
                #[inline]
                pub const fn len_eof_en(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// Configures whether or not to enable data integrity check by appending a 16 bit CCITT-CRC to the end of the data.\\ 0: Disable\\ 1: Enable\\
                #[inline]
                pub const fn encode_crc_en(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Configures clock gating.\\ 0: Support clock only when the application writes registers.\\ 1: Always force the clock on for registers.\\
                #[inline]
                pub const fn clk_en(self) -> bool {
                    (self.0 & 0x00000800) != 0
                }

                /// Configures whether or not to stop UHCI from receiving data after UART has received a NULL frame.\\ 0: Not stop\\ 1: Stop\\
                #[inline]
                pub const fn uart_rx_brk_eof_en(self) -> bool {
                    (self.0 & 0x00001000) != 0
                }
            }
        }

