        /// The `CONF` register.
        ///
        /// zero det cfg reg
        pub mod conf {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffffffff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// vref pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn vref_channel_sel(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Channel 3 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_3_sel(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 4)
                }

                /// Channel 2 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_2_sel(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 8)
                }

                /// Channel 1 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_1_sel(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 12)
                }

                /// enable channel 3 event timer to trigger channel 1 event after pad_comp_channel_3_int
                #[inline]
                pub const fn channel_3_event_timer_en(self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// enable channel 2 event timer to trigger channel 1 event after pad_comp_channel_2_int
                #[inline]
                pub const fn channel_2_event_timer_en(self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// enable channel 1 event timer to trigger channel 1 event after pad_comp_channel_1_int
                #[inline]
                pub const fn channel_1_event_timer_en(self) -> bool {
                    (self.0 & 0x00040000) != 0
                }

                /// enable timer to record the time between two continuous zero det int in each channel
                #[inline]
                pub const fn channel_timer_en(self) -> bool {
                    (self.0 & 0x00080000) != 0
                }

                /// cfg continuous zero det num to change zero det result
                #[inline]
                pub const fn limit_cnt(self) -> u8 {
                    (self.0 >> 20) as u8
                }

                /// mask channel to do pad compare and zero det
                #[inline]
                pub const fn comp_poll_mask(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 28)
                }

                /// cfg channel scan mode ,0 means one trigger scan all mask channel, 1 means one trigger scan one mask channel
                #[inline]
                pub const fn comp_poll_mode(self) -> bool {
                    (self.0 & 0x80000000) != 0
                }
            }

            /// The register's value while it is changed.
            pub struct W(pub(super) u32);

            impl W {
                /// vref pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn vref_channel_sel(&self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Channel 3 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_3_sel(&self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 4)
                }

                /// Channel 2 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_2_sel(&self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 8)
                }

                /// Channel 1 comp pad sel,one hot code and cannot set the same bit with other channels
                #[inline]
                pub const fn comp_channel_1_sel(&self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 12)
                }

                /// enable channel 3 event timer to trigger channel 1 event after pad_comp_channel_3_int
                #[inline]
                pub const fn channel_3_event_timer_en(&self) -> bool {
                    (self.0 & 0x00010000) != 0
                }

                /// enable channel 2 event timer to trigger channel 1 event after pad_comp_channel_2_int
                #[inline]
                pub const fn channel_2_event_timer_en(&self) -> bool {
                    (self.0 & 0x00020000) != 0
                }

                /// enable channel 1 event timer to trigger channel 1 event after pad_comp_channel_1_int
                #[inline]
                pub const fn channel_1_event_timer_en(&self) -> bool {
                    (self.0 & 0x00040000) != 0
                }

                /// enable timer to record the time between two continuous zero det int in each channel
                #[inline]
                pub const fn channel_timer_en(&self) -> bool {
                    (self.0 & 0x00080000) != 0
                }

                /// cfg continuous zero det num to change zero det result
                #[inline]
                pub const fn limit_cnt(&self) -> u8 {
                    (self.0 >> 20) as u8
                }

                /// mask channel to do pad compare and zero det
                #[inline]
                pub const fn comp_poll_mask(&self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 28)
                }

                /// cfg channel scan mode ,0 means one trigger scan all mask channel, 1 means one trigger scan one mask channel
                #[inline]
                pub const fn comp_poll_mode(&self) -> bool {
                    (self.0 & 0x80000000) != 0
                }

                /// Set `VREF_CHANNEL_SEL`.
                #[inline]
                pub fn set_vref_channel_sel(&mut self, value: oer_mmio::Bits<4>) -> &mut Self {
                    self.0 = (self.0 & !0x0000000f) | value.get();
                    self
                }

                /// Set `COMP_CHANNEL_3_SEL`.
                #[inline]
                pub fn set_comp_channel_3_sel(&mut self, value: oer_mmio::Bits<4>) -> &mut Self {
                    self.0 = (self.0 & !0x000000f0) | (value.get() << 4);
                    self
                }

                /// Set `COMP_CHANNEL_2_SEL`.
                #[inline]
                pub fn set_comp_channel_2_sel(&mut self, value: oer_mmio::Bits<4>) -> &mut Self {
                    self.0 = (self.0 & !0x00000f00) | (value.get() << 8);
                    self
                }

                /// Set `COMP_CHANNEL_1_SEL`.
                #[inline]
                pub fn set_comp_channel_1_sel(&mut self, value: oer_mmio::Bits<4>) -> &mut Self {
                    self.0 = (self.0 & !0x0000f000) | (value.get() << 12);
                    self
                }

                /// Set `CHANNEL_3_EVENT_TIMER_EN`.
                #[inline]
                pub fn set_channel_3_event_timer_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x00010000) | (u32::from(value) << 16);
                    self
                }

                /// Set `CHANNEL_2_EVENT_TIMER_EN`.
                #[inline]
                pub fn set_channel_2_event_timer_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x00020000) | (u32::from(value) << 17);
                    self
                }

                /// Set `CHANNEL_1_EVENT_TIMER_EN`.
                #[inline]
                pub fn set_channel_1_event_timer_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x00040000) | (u32::from(value) << 18);
                    self
                }

                /// Set `CHANNEL_TIMER_EN`.
                #[inline]
                pub fn set_channel_timer_en(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x00080000) | (u32::from(value) << 19);
                    self
                }

                /// Set `LIMIT_CNT`.
                #[inline]
                pub fn set_limit_cnt(&mut self, value: u8) -> &mut Self {
                    self.0 = (self.0 & !0x0ff00000) | (u32::from(value) << 20);
                    self
                }

                /// Set `COMP_POLL_MASK`.
                #[inline]
                pub fn set_comp_poll_mask(&mut self, value: oer_mmio::Bits<3>) -> &mut Self {
                    self.0 = (self.0 & !0x70000000) | (value.get() << 28);
                    self
                }

                /// Set `COMP_POLL_MODE`.
                #[inline]
                pub fn set_comp_poll_mode(&mut self, value: bool) -> &mut Self {
                    self.0 = (self.0 & !0x80000000) | (u32::from(value) << 31);
                    self
                }
            }
        }

